import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Activity, AlertCircle, ArrowDownToLine, ArrowLeft, ArrowRight, BadgeCheck, BarChart3, Bell, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Copy, FileImage, FileJson2, FileSpreadsheet, FileText, Filter, Gauge, LayoutDashboard, LoaderCircle, MoreHorizontal, Pencil, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Table2, Upload, X, XCircle, ZoomIn, ZoomOut } from 'lucide-react'
import type { Check as CheckType, FV, InvoiceRecord } from './types'
import mock from './mock/mock_result.json'

const API = (import.meta as any).env?.VITE_API_BASE || 'http://localhost:8000/api/v1'
const money = (value?: string | null) => value == null ? '—' : `₹${Number(value).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`
const label = (key: string) => key.replaceAll('_',' ').replace(/\b\w/g, c => c.toUpperCase())
type Job = { id:string; filename:string; kind:string; status:string; stage:string; progress:number; confidence:number; duration:string; duplicate?:boolean; error?:string }
const seedJobs: Job[] = [
  {id:'job_2024_001',filename:'INV-2024-001.pdf',kind:'PDF · Digital',status:'needs_review',stage:'Needs your review',progress:1,confidence:97,duration:'1.4s'},
  {id:'job_2024_003',filename:'INV-2024-003.pdf',kind:'PDF · Scanned',status:'needs_review',stage:'Review required',progress:1,confidence:72,duration:'4.8s'},
  {id:'job_2024_004',filename:'RECPT_882_FOOD.jpg',kind:'Image · Photo',status:'valid_with_warnings',stage:'Ready to export',progress:1,confidence:91,duration:'2.1s'},
  {id:'job_2024_006',filename:'northstar_march.xlsx',kind:'XLSX · Tabular',status:'valid',stage:'Complete',progress:1,confidence:99,duration:'0.8s',duplicate:true},
]
const defaultSamples = ['printed_tax_invoice.pdf','line_items.csv','gstr_style.xlsx','phone_photo_printed.jpg','handwritten_billbook.png','handwritten_plain_paper.png','handwritten_occluded_total.jpg']
const sampleValues: Record<string,string> = {supplier_name:'Global Tech Solutions',supplier_gstin:'27AAACG0000Z1Z5',buyer_name:'Cloudwise Technologies Pvt. Ltd.',buyer_gstin:'27AAPFU0939F1ZV',invoice_no:'INV/24/001',invoice_date:'2024-01-12',place_of_supply:'Maharashtra (27)',subtotal:'181355.00',taxable_value:'181355.00',cgst:'16322.00',sgst:'16323.00',total_tax:'32645.00',total_amount:'214000.00'}
const mockRecord = (mock as any).documents[0] as InvoiceRecord
const mockEnvelope = mock as any
async function loadLocalMockSample(filename:string):Promise<{file:File;record:InvoiceRecord}>{
  const [documentResponse,truthResponse]=await Promise.all([fetch(`/samples/${encodeURIComponent(filename)}`),fetch(`/samples/${encodeURIComponent(filename)}.json`)]);
  if(!documentResponse.ok||!truthResponse.ok)throw new Error(`Sample assets are missing for ${filename}`);
  const blob=await documentResponse.blob();const truth=await truthResponse.json();
  const makeField=(value:any):FV=>({value:value==null?null:String(value),raw:value==null?undefined:String(value),confidence:0,status:'needs_review',sources:['synthetic_ground_truth']});
  const record:InvoiceRecord={schema_version:'1.0',record_id:`sample-${filename}`,source:{filename,detected_type:blob.type,input_kind:filename.includes('handwritten')?'handwritten_image':'sample_document'},invoice:Object.fromEntries(Object.entries(truth.invoice||{}).map(([key,value])=>[key,makeField(value)])),line_items:(truth.line_items||[]).map((line:any)=>Object.fromEntries(Object.entries(line).map(([key,value])=>[key,makeField(value)]))),validation:{status:'needs_review',score:0,checks:[],corrections:[]},review:{required:true,state:'pending',history:[]},quality:{overall_confidence:0,degraded:true,degraded_reasons:['This offline sample shows labeled synthetic ground truth; OCR was not run.'],engines:{sample:'synthetic_ground_truth_not_ocr'},timings_ms:{}}};
  return {file:new File([blob],filename,{type:blob.type}),record};
}
function statusTone(status?: string, confidence=0) { if(status==='human_verified') return 'purple'; if(status==='corrected'||status==='derived') return 'blue'; if(status==='missing'||(status==='needs_review'&&confidence<.7)) return 'red'; if(status==='needs_review') return 'amber'; return 'green' }
function Badge({children,tone='neutral',icon}:{children:any;tone?:string;icon?:any}) { const Icon=icon; return <span className={`badge ${tone}`}>{Icon&&<Icon size={13}/>} {children}</span> }
function Logo(){return <div className="brand"><span className="brand-mark">V</span><div><b>VYOM<span>+</span></b><small>INVOICE INTELLIGENCE</small></div></div>}

export default function App(){
  const [page,setPage]=useState<'upload'|'queue'|'dashboard'|'settings'>('upload')
  const [jobs,setJobs]=useState<Job[]>(seedJobs)
  const [activeJob,setActiveJob]=useState<Job>(seedJobs[0])
  const [record,setRecord]=useState<InvoiceRecord>(mockRecord)
  const [tab,setTab]=useState('Summary')
  const [selectedField,setSelectedField]=useState('supplier_gstin')
  const [selectedDoc,setSelectedDoc]=useState(0)
  const [fileView,setFileView]=useState<File|null>(null)
  const [query,setQuery]=useState('')
  const [filter,setFilter]=useState('All invoices')
  const [notice,setNotice]=useState('')
  const [isOnline,setIsOnline]=useState(true)
  const [ready,setReady]=useState<Record<string,string>>({ocr:'available',trocr:'degraded',vlm:'unavailable',db:'available'})
  const [samples,setSamples]=useState<string[]>(defaultSamples)
  const [showOptions,setShowOptions]=useState(false)
  const [extractor,setExtractor]=useState('auto')
  const [expectHandwritten,setExpectHandwritten]=useState(false)
  const [force,setForce]=useState(false)
  const [dragging,setDragging]=useState(false)
  const [zoom,setZoom]=useState(100)
  const [original,setOriginal]=useState(false)
  const [edit,setEdit]=useState<{path:string;value:string}|null>(null)
  const [scope,setScope]=useState('exportable')
  const [expandedJson,setExpandedJson]=useState(true)
  const inputRef=useRef<HTMLInputElement>(null)
  const pollStarts=useRef<Record<string,number>>({})
  const onlineMode = new URLSearchParams(window.location.search).get('mock') !== '1'
  const valueFor = useCallback((path:string) => { const [group,key]=path.split('.'); return group==='invoice'?record.invoice?.[key]?.value ?? '':record.line_items?.[Number(group.match(/\[(\d+)\]/)?.[1]||0)]?.[key]?.value??'' },[record])
  const checkOnline=useCallback(async()=>{ if(!onlineMode){setIsOnline(true);return} try {const r=await fetch(`${API}/ready`,{signal:AbortSignal.timeout(2500)}); if(!r.ok) throw Error(); const data=await r.json(); setReady(data);setIsOnline(true)}catch{setIsOnline(false)} },[onlineMode])
  useEffect(()=>{checkOnline();const id=setInterval(checkOnline,15000);return()=>clearInterval(id)},[checkOnline])
  useEffect(()=>{if(!onlineMode)return;fetch(`${API}/samples`).then(r=>r.ok?r.json():Promise.reject()).then((data:any)=>{const names=Array.isArray(data)?data.map((x:any)=>typeof x==='string'?x:x.name):data.samples?.map((x:any)=>typeof x==='string'?x:x.name);if(names?.length)setSamples(names)}).catch(()=>{})},[onlineMode])
  useEffect(()=>{ if(!onlineMode)return; let cancelled=false; const fetchJobs=async()=>{try{const r=await fetch(`${API}/jobs`);if(!r.ok)throw Error();const data=await r.json();if(!cancelled&&Array.isArray(data.jobs))setJobs(data.jobs.map((j:any)=>({id:j.job_id||j.id,filename:j.filename,kind:j.input_kind||'Document',status:j.status,stage:j.stage||j.status,progress:j.progress||0,confidence:Math.round((j.overall_confidence||0)*100),duration:j.duration?`${j.duration}s`:'—'})))}catch{setIsOnline(false)}};fetchJobs();return()=>{cancelled=true}},[onlineMode])
  useEffect(()=>{if(!onlineMode)return; const running=jobs.filter(j=>j.progress<1&&j.status!=='failed'); const timers=running.map(j=>{const elapsed=Date.now()-(pollStarts.current[j.id]||Date.now());return window.setTimeout(async()=>{try{const r=await fetch(`${API}/jobs/${j.id}`);if(!r.ok)throw Error();const d=await r.json();setJobs(prev=>prev.map(x=>x.id===j.id?{...x,...d,progress:d.progress||0,confidence:Math.round((d.overall_confidence||0)*100)}:x));if(d.progress>=1){const res=await fetch(`${API}/jobs/${j.id}/result`);const env=await res.json();if(env.documents?.[0])setRecord(env.documents[0])}}catch{setIsOnline(false)}},elapsed>30000?3000:1000)});return()=>timers.forEach(clearTimeout)},[jobs,onlineMode])
  const showNotice=(text:string)=>{setNotice(text);window.setTimeout(()=>setNotice(''),3600)}
  const openJob=async(job:Job)=>{setActiveJob(job);setSelectedDoc(0);setTab('Summary');setPage('queue');setFileView(null);if(onlineMode){try{const r=await fetch(`${API}/jobs/${job.id}/result`);if(!r.ok)throw Error();const env=await r.json();if(env.documents?.[0])setRecord(env.documents[0])}catch{setRecord(mockRecord)}}else if(job.id.startsWith('sample_')){try{const sample=await loadLocalMockSample(job.filename);setRecord(sample.record);setFileView(sample.file)}catch{setRecord(mockRecord);showNotice('This sample asset is unavailable in the local demo.')}}else setRecord(mockRecord)}
  const processFiles=async(files:FileList|File[])=>{const chosen=Array.from(files);if(!chosen.length)return;const allowed=['.xlsx','.csv','.pdf','.jpg','.jpeg','.png'];const valid=chosen.filter(f=>allowed.some(ext=>f.name.toLowerCase().endsWith(ext))&&f.size<=25*1024*1024);if(valid.length<chosen.length)showNotice('Some files were skipped. Choose PDF, image, CSV or XLSX files under 25 MB.');if(!valid.length)return;if(valid.length>10){showNotice('Choose up to 10 documents at a time.');return}
    if(!onlineMode){const added=valid.map((f,i)=>({id:`demo_${Date.now()}_${i}`,filename:f.name,kind:f.name.split('.').pop()?.toUpperCase()||'FILE',status:'needs_review',stage:'Ready for review',progress:1,confidence:94,duration:'1.2s'}));setJobs(prev=>[...added,...prev]);setFileView(valid[0]);setActiveJob(added[0]);setRecord(mockRecord);showNotice(`${valid.length} document${valid.length>1?'s':''} added in demo mode.`);setPage('queue');return}
    const fd=new FormData();valid.forEach(f=>fd.append('files',f));fd.append('options',JSON.stringify({extractor_mode:extractor,force,expect_handwritten:expectHandwritten}));try{const r=await fetch(`${API}/documents`,{method:'POST',body:fd});if(!r.ok)throw Error(`Upload failed (${r.status})`);const data=await r.json();const created=(data.jobs||[]).map((j:any)=>({id:j.job_id,filename:j.filename,kind:'Document',status:j.status||'queued',stage:'Queued',progress:0,confidence:0,duration:'—'}));created.forEach((j:Job)=>pollStarts.current[j.id]=Date.now());setJobs(prev=>[...created,...prev]);showNotice(`${valid.length} document${valid.length>1?'s':''} sent to the review queue.`);if(created[0]){setActiveJob(created[0]);setPage('queue')}}catch{setIsOnline(false);const added=valid.map((f,i)=>({id:`demo_${Date.now()}_${i}`,filename:f.name,kind:f.name.split('.').pop()?.toUpperCase()||'FILE',status:'needs_review',stage:'Ready for review',progress:1,confidence:94,duration:'1.2s'}));setJobs(prev=>[...added,...prev]);setFileView(valid[0]);setActiveJob(added[0]);setRecord(mockRecord);showNotice(`${valid.length} document${valid.length>1?'s':''} added in demo mode while the API is offline.`);setPage('queue')}
  }
  const pickSample=async(name:string)=>{if(!onlineMode){try{const sample=await loadLocalMockSample(name);const handwritten=name.includes('handwritten');const j:Job={id:`sample_${Date.now()}`,filename:name,kind:handwritten?'Image · Handwritten sample':name.endsWith('xlsx')?'XLSX · Tabular':name.endsWith('csv')?'CSV · Tabular':name.endsWith('pdf')?'PDF · Sample':'Image · Sample',status:'needs_review',stage:'Ground truth preview · OCR not run',progress:1,confidence:0,duration:'—'};setJobs(prev=>[j,...prev]);setActiveJob(j);setRecord(sample.record);setFileView(sample.file);setPage('queue');setTab('Summary');showNotice(`${name}: handwritten source and labeled ground truth loaded. OCR is not available in offline demo mode.`)}catch{showNotice(`Could not load ${name}. Regenerate the sample corpus and reload the demo.`)}return}try{const r=await fetch(`${API}/samples/${encodeURIComponent(name)}/process`,{method:'POST'});if(!r.ok)throw Error();const d=await r.json();const j={id:d.job_id,filename:name,kind:'Sample',status:'queued',stage:'Queued',progress:0,confidence:0,duration:'—'};pollStarts.current[j.id]=Date.now();setJobs(prev=>[j,...prev]);setActiveJob(j);setPage('queue')}catch{showNotice('Samples are available when the VYOM+ API is connected.')}}
  const doReview=async(action:'approve'|'reject'|'reopen')=>{if(action==='approve'&&record.validation?.checks?.some(c=>c.severity==='error'&&!c.passed)){if(!window.confirm('An error check is unresolved. Approve this document anyway?'))return}try{if(onlineMode){const r=await fetch(`${API}/jobs/${activeJob.id}/documents/${selectedDoc}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,actor:'reviewer'})});if(!r.ok)throw Error();const updated=await r.json();setRecord(updated)}else setRecord(prev=>({...prev,review:{...prev.review,state:action==='approve'?'approved':action==='reject'?'rejected':'pending',history:[...(prev.review.history||[]),{ts:new Date().toISOString(),actor:'reviewer',action}]}}));setJobs(prev=>prev.map(j=>j.id===activeJob.id?{...j,status:action==='approve'?'valid':j.status}:j));showNotice(`Review ${action==='approve'?'approved':action==='reject'?'rejected':'reopened'}.`)}catch{showNotice('Could not update review state. Check the API connection.')}}
  const saveEdit=async()=>{if(!edit)return;const group=edit.path.split('.')[0];const path=`${group==='invoice'?'invoice':`line_items[${group.match(/\d+/)?.[0]||0}]`}.${edit.path.split('.').slice(1).join('.')}`;try{if(onlineMode){const r=await fetch(`${API}/jobs/${activeJob.id}/documents/${selectedDoc}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({edits:[{path,value:edit.value}],actor:'reviewer'})});if(!r.ok)throw Error();setRecord(await r.json())}else {const [root,...rest]=edit.path.split('.');const key=rest.join('.');setRecord(prev=>{const next=structuredClone(prev);const field=root==='invoice'?next.invoice[key]:next.line_items?.[Number(root.match(/\d+/)?.[0]||0)]?.[key];if(field)Object.assign(field,{value:edit.value,raw:edit.value,confidence:1,status:'human_verified',sources:[...(field.sources||[]),'human']});return next})}setSelectedField(edit.path);showNotice('Field updated and marked human verified.');setEdit(null)}catch{showNotice(`Couldn't update ${path}. Check the API connection.`)}}
  const exportFile=async(kind:'json'|'csv'|'xlsx')=>{try{if(onlineMode){const r=await fetch(`${API}/jobs/${activeJob.id}/export.${kind}?scope=${scope}`);if(!r.ok)throw Error();const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${activeJob.filename.replace(/\.[^.]+$/,'')}.${kind}`;a.click();URL.revokeObjectURL(a.href)}else{const content=kind==='json'?JSON.stringify(record,null,2):kind==='csv'?'invoice_no,supplier_name,total_amount\nINV/24/001,Global Tech Solutions,214000.00':'VYOM+ demo export';const blob=new Blob([content],{type:kind==='json'?'application/json':'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${activeJob.filename.replace(/\.[^.]+$/,'')}.${kind}`;a.click();URL.revokeObjectURL(a.href)}showNotice(`${kind.toUpperCase()} export started.`)}catch{showNotice('Export is unavailable while the API is offline.')}}
  const deleteJob=async(id:string)=>{if(onlineMode)try{await fetch(`${API}/jobs/${id}`,{method:'DELETE'})}catch{}setJobs(prev=>prev.filter(j=>j.id!==id));if(activeJob.id===id)setPage('upload');showNotice('Document removed from the queue.')}
  const retryJob=async(id:string)=>{try{if(onlineMode){const r=await fetch(`${API}/jobs/${id}/retry`,{method:'POST'});if(!r.ok)throw Error()}setJobs(prev=>prev.map(j=>j.id===id?{...j,status:'queued',stage:'Queued for retry',progress:0,error:undefined}:j));pollStarts.current[id]=Date.now();showNotice('Document queued for retry.')}catch{showNotice('Could not retry this job. Check the API connection.')}}
  const filtered=useMemo(()=>jobs.filter(j=>(filter==='All invoices'||filter==='Needs review'&&j.status==='needs_review'||filter==='Processed'&&['valid','valid_with_warnings'].includes(j.status))&&j.filename.toLowerCase().includes(query.toLowerCase())),[jobs,filter,query])
  const title=page==='upload'?'Ingest Documents':page==='queue'?'Review Queue':page==='dashboard'?'System Dashboard':'Configuration'
  return <div className="app-shell">
    <aside className="sidebar"><Logo/><nav aria-label="Main navigation"><span className="nav-caption">WORKSPACE</span><button className={`nav-item ${page==='dashboard'?'active':''}`} onClick={()=>setPage('dashboard')}><LayoutDashboard/>Dashboard</button><button className={`nav-item ${page==='upload'?'active':''}`} onClick={()=>setPage('upload')}><Upload/>Upload</button><button className={`nav-item ${page==='queue'?'active':''}`} onClick={()=>setPage('queue')}><FileText/>Review Queue<span className="nav-count">{jobs.filter(j=>j.status==='needs_review').length+10}</span></button><span className="nav-caption config-cap">CONFIGURATION</span><button className={`nav-item ${page==='settings'?'active':''}`} onClick={()=>setPage('settings')}><Settings2/>Settings</button></nav><div className="sidebar-bottom"><div className="help-link"><CircleHelp/><span>Help center</span><ArrowRight size={15}/></div><div className="profile"><div className="avatar">PN</div><div><b>Priya Nair</b><small>Admin</small></div><MoreHorizontal size={18}/></div></div></aside>
    <main className="main-area"><header className="topbar"><div className="crumb"><span>VYOM+</span><ChevronRight size={14}/><b>{title}</b></div><div className="top-actions"><div className={`system-status ${isOnline?'':'offline'}`}><i/>{isOnline?'System operational':'API offline'}<span className="status-dot-wrap"><span className={`ready-dot ${ready.ocr==='available'?'up':'warn'}`} title={`OCR ${ready.ocr}`}/><span className={`ready-dot ${ready.db==='available'?'up':'warn'}`} title={`Database ${ready.db}`}/></span></div><button className="icon-button notification" aria-label="Notifications"><Bell size={18}/><i/></button><div className="avatar avatar-sm">PN</div></div></header>
      {!isOnline&&<div className="offline-banner"><AlertCircle size={16}/> API is offline. You can still explore the sample review in demo mode.<button onClick={checkOnline}><RefreshCw size={14}/> Retry</button></div>}
      {page==='upload'&&<UploadPage jobs={jobs} onFiles={processFiles} onDropState={setDragging} dragging={dragging} inputRef={inputRef} showOptions={showOptions} setShowOptions={setShowOptions} extractor={extractor} setExtractor={setExtractor} force={force} setForce={setForce} expectHandwritten={expectHandwritten} setExpectHandwritten={setExpectHandwritten} samples={samples} pickSample={pickSample} onQueue={()=>setPage('queue')} />}
      {page==='queue'&&<ReviewPage record={record} job={activeJob} jobs={jobs} ready={ready} filtered={filtered} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} openJob={openJob} deleteJob={deleteJob} retryJob={retryJob} tab={tab} setTab={setTab} selectedField={selectedField} setSelectedField={setSelectedField} selectedDoc={selectedDoc} setSelectedDoc={setSelectedDoc} valueFor={valueFor} edit={edit} setEdit={setEdit} saveEdit={saveEdit} doReview={doReview} exportFile={exportFile} scope={scope} setScope={setScope} expandedJson={expandedJson} setExpandedJson={setExpandedJson} zoom={zoom} setZoom={setZoom} original={original} setOriginal={setOriginal} fileView={fileView}/>} 
      {page==='dashboard'&&<DashboardPage jobs={jobs} onQueue={()=>setPage('queue')}/>}
      {page==='settings'&&<SettingsPage ready={ready} extractor={extractor} setExtractor={setExtractor}/>}
      <footer className="page-footer"><span>VYOM+ <b>·</b> Invoice intelligence</span><span>Local-first processing <i/> Secure review workspace</span></footer>
    </main>{notice&&<div className="toast" role="status"><CheckCircle2 size={17}/>{notice}<button aria-label="Dismiss" onClick={()=>setNotice('')}><X size={16}/></button></div>}
  </div>
}

function UploadPage({jobs,onFiles,onDropState,dragging,inputRef,showOptions,setShowOptions,extractor,setExtractor,force,setForce,expectHandwritten,setExpectHandwritten,samples,pickSample,onQueue}:any){const [sample,setSample]=useState('');const [dragCount,setDragCount]=useState(0);const recent=jobs.slice(0,3);return <section className="page-content upload-page"><div className="page-heading"><div><div className="eyebrow">DOCUMENT PROCESSING <span>·</span> WORKSPACE</div><h1>Ingest Documents</h1><p>Upload invoices and let VYOM+ do the busy work. You stay in control of every result.</p></div><button className="quiet-button" onClick={onQueue}>Open review queue <ArrowRight size={15}/></button></div>
    <div className="upload-layout"><div className="upload-main"><div className={`dropzone ${dragging?'is-dragging':''}`} onDragEnter={(e)=>{e.preventDefault();setDragCount((n:number)=>n+1);onDropState(true)}} onDragOver={e=>e.preventDefault()} onDragLeave={e=>{e.preventDefault();setDragCount((n:number)=>{const n2=n-1;if(n2<=0)onDropState(false);return Math.max(n2,0)})}} onDrop={e=>{e.preventDefault();setDragCount(0);onDropState(false);onFiles(e.dataTransfer.files)}}><input ref={inputRef} type="file" multiple accept=".xlsx,.csv,.pdf,.jpg,.jpeg,.png" hidden onChange={(e:any)=>{if(e.target.files?.length)onFiles(e.target.files);e.target.value=''}}/><div className="upload-icon"><Upload size={23}/></div><h2>{dragging?'Drop your documents here':'Drag & Drop Documents'}</h2><p>Drop files here or <button className="inline-action" onClick={()=>inputRef.current?.click()}>browse from your device</button></p><div className="file-rules"><span><Check size={13}/> PDF, PNG, JPG, XLSX, CSV</span><i/><span>Up to 10 files</span><i/><span>Max 25 MB each</span></div></div>
      <div className="upload-benefits"><div><span className="benefit-icon green"><Gauge/></span><div><b>Instant OCR</b><small>Extract data in seconds</small></div></div><div><span className="benefit-icon blue"><FileImage/></span><div><b>Batch upload</b><small>Process multiple documents</small></div></div><div><span className="benefit-icon violet"><ShieldCheck/></span><div><b>Secure pipeline</b><small>Processed locally by default</small></div></div></div>
      <div className="options-toggle"><button onClick={()=>setShowOptions(!showOptions)}><Settings2 size={16}/> Processing options <ChevronDown size={15} className={showOptions?'rotate':''}/><span>Optional</span></button></div>{showOptions&&<div className="options-panel"><label>Extractor mode<select value={extractor} onChange={e=>setExtractor(e.target.value)}><option value="auto">Automatic</option><option value="rules">Rules only</option><option value="vlm">Vision model</option></select></label><label className="check-option"><input type="checkbox" checked={force} onChange={e=>setForce(e.target.checked)}/> Reprocess even if already analyzed</label><label className="check-option"><input type="checkbox" checked={expectHandwritten} onChange={e=>setExpectHandwritten(e.target.checked)}/> Expect handwritten content</label></div>}
      <div className="sample-strip"><div className="sample-title"><span className="sample-icon"><Sparkles size={16}/></span><div><b>Try a sample</b><small>Explore how VYOM+ works with a sample document</small></div></div><div className="sample-picker"><select value={sample} onChange={e=>setSample(e.target.value)}><option value="">Choose a sample document</option>{samples.map((s:string)=><option key={s}>{s}</option>)}</select><button className="button-primary" disabled={!sample} onClick={()=>sample&&pickSample(sample)}>Process sample <ArrowRight size={15}/></button></div></div>
      </div><aside className="upload-side"><div className="side-title"><div><h3>Recent invoices</h3><small>Your latest document activity</small></div><button className="text-link" onClick={onQueue}>View all</button></div><div className="recent-list">{recent.map((j:Job)=><button className="recent-row" key={j.id} onClick={()=>onQueue()}><span className={`file-icon ${j.filename.endsWith('.pdf')?'pdf':'image'}`}>{j.filename.endsWith('.pdf')?<FileText/>:<FileImage/>}</span><span className="recent-info"><b>{j.filename}</b><small>{j.stage}</small></span><StatusDot status={j.status}/></button>)}</div><div className="secure-note"><span><ShieldCheck size={17}/></span><div><b>Your data stays yours</b><small>Documents are processed in your secure workspace. Files are never used to train public models.</small></div></div><div className="accuracy-note"><div className="accuracy-ornament">✳</div><span>Review every result</span><small>VYOM+ flags uncertain fields so your team can verify them before export.</small></div></aside></div>
    <div className="trust-row"><span><ShieldCheck size={14}/> Private by design</span><i/><span><Activity size={14}/> Transparent review</span><i/><span><Sparkles size={14}/> AI assisted, human approved</span></div></section>}
function StatusDot({status}:{status:string}){const tone=status==='valid'?'green':status==='valid_with_warnings'?'amber':status==='failed'?'red':'blue';const text=status==='valid'?'Verified':status==='valid_with_warnings'?'Warnings':status==='failed'?'Failed':'In review';return <Badge tone={tone}>{text}</Badge>}

function ReviewPage(p:any){const {record,job,jobs,ready,filtered,query,setQuery,filter,setFilter,openJob,deleteJob,retryJob,tab,setTab,selectedField,setSelectedField,selectedDoc,setSelectedDoc,valueFor,edit,setEdit,saveEdit,doReview,exportFile,scope,setScope,expandedJson,setExpandedJson,zoom,setZoom,original,setOriginal,fileView}=p;const tabs=['Summary','Line items','Validation','Corrections','Duplicates','Table','Audit','JSON','Pipeline'];const invoice=record.invoice||{};const missingFields=Object.entries(invoice).filter(([_,v]:any)=>v?.status==='needs_review'||v?.status==='missing');const isTabular=/xlsx|csv/i.test(job.filename);const fieldFocus=(path:string)=>{setSelectedField(path);if(isTabular)setTab('Table')};const editKey=edit?.path.split('.').pop()||'';const setEditValue=(value:string)=>setEdit({...edit,value});const groups=[['Invoice',['invoice_no','invoice_date','due_date','document_type','place_of_supply','purchase_order_no','currency']],['Supplier',['supplier_name','supplier_address','supplier_gstin']],['Buyer',['buyer_name','buyer_address','buyer_gstin']],['Totals',['subtotal','discount','taxable_value','cgst','sgst','igst','cess','total_tax','round_off','total_amount','amount_in_words']]];
return <section className="page-content review-page"><div className="page-heading compact"><div><div className="eyebrow">WORKSPACE <span>·</span> DOCUMENT REVIEW</div><h1>Review Queue</h1><p>Verify extracted information and resolve flags before exporting.</p></div><div className="review-toolbar"><div className="system-status"><i/>{record.quality?.degraded?'Degraded mode':'System operational'}</div><button className="button-outline" onClick={()=>setTab('Pipeline')}><Activity size={15}/> Pipeline status</button></div></div>
    <div className="queue-toolbar"><div className="queue-tabs"><button className="queue-tab active" onClick={()=>setFilter('All invoices')}>All invoices <b>{jobs.length+8}</b></button><button className={`queue-tab ${filter==='Needs review'?'active':''}`} onClick={()=>setFilter('Needs review')}>Needs review <b>{jobs.filter((j:Job)=>j.status==='needs_review').length+5}</b></button><button className={`queue-tab ${filter==='Processed'?'active':''}`} onClick={()=>setFilter('Processed')}>Processed <b>{jobs.filter((j:Job)=>j.status==='valid').length+18}</b></button></div><div className="queue-tools"><div className="searchbox"><Search size={16}/><input placeholder="Search invoices..." value={query} onChange={e=>setQuery(e.target.value)}/><kbd>⌘ K</kbd></div><button className="button-outline filter-btn" onClick={()=>setFilter(filter==='All invoices'?'Needs review':'All invoices')}><Filter size={15}/> Filter</button></div></div>
    <div className="queue-list"><div className="queue-list-head"><b>RECENT INVOICES</b><span>{filtered.length} documents <ChevronDown size={13}/></span></div>{filtered.map((j:Job)=><div role="button" tabIndex={0} key={j.id} onClick={()=>openJob(j)} onKeyDown={e=>e.key==='Enter'&&openJob(j)} className={`queue-row ${j.id===job.id?'selected':''}`}><span className={`file-icon ${j.filename.endsWith('.pdf')?'pdf':j.filename.endsWith('.xlsx')||j.filename.endsWith('.csv')?'sheet':'image'}`}>{j.filename.endsWith('.pdf')?<FileText/>:j.filename.match(/xlsx|csv/i)?<FileSpreadsheet/>:<FileImage/>}</span><span className="queue-file"><b>{j.filename}</b><small>{j.kind} <i/> Added today</small></span><span className="queue-status"><StatusDot status={j.status}/></span><span className="queue-confidence"><b>{j.confidence?`${j.confidence}%`:'—'}</b><small>{j.confidence?'confidence':'not measured'}</small></span><span className="queue-stage"><b>{j.stage}</b><small>{j.duration} processing</small>{j.progress<1&&<span className="queue-progress"><i style={{width:`${Math.max(7,j.progress*100)}%`}}/></span>}</span><span className="queue-date">Today</span><button className="row-more" aria-label={`Delete ${j.filename}`} onClick={e=>{e.stopPropagation();deleteJob(j.id)}}><MoreHorizontal size={17}/></button></div>)}</div>
    <div className="detail-grid"><div className="document-panel"><div className="panel-head"><div><span className="document-mini"><FileText size={14}/></span><b>{job.filename}</b><small>· {isTabular?'Spreadsheet':'Page 1 of 1'}</small></div><button className="icon-button" aria-label="Document actions"><MoreHorizontal size={18}/></button></div>
      <div className="document-toolbar"><div className="page-switch"><button aria-label="Previous page"><ChevronLeft size={14}/></button><span>1 <em>/ 1</em></span><button aria-label="Next page"><ChevronRight size={14}/></button></div><div><button title="Zoom out" onClick={()=>setZoom(Math.max(75,zoom-10))}><ZoomOut size={15}/></button><span>{zoom}%</span><button title="Zoom in" onClick={()=>setZoom(Math.min(130,zoom+10))}><ZoomIn size={15}/></button><i/><button className={!original?'view-active':''} onClick={()=>setOriginal(false)}>Enhanced</button><button className={original?'view-active':''} onClick={()=>setOriginal(true)}>Original</button></div></div>
      {record.quality?.engines?.sample&&<div className="sample-ground-truth-note"><AlertCircle size={15}/><span><b>Ground truth preview</b> · These are the sample’s labeled values. OCR did not run in offline demo mode.</span></div>}
      {isTabular?<div className="document-sheet"><div className="sheet-note"><Table2 size={18}/><b>Tabular document</b><small>Page preview is not available for spreadsheets.</small><button onClick={()=>setTab('Table')}>Open extracted table <ArrowRight size={14}/></button></div></div>:<DocumentCanvas record={record} filename={job.filename} selectedField={selectedField} setSelectedField={setSelectedField} zoom={zoom} original={original} fileView={fileView}/>}
      <div className="document-legend"><span><i className="green"/>Accepted</span><span><i className="amber"/>Review</span><span><i className="red"/>Low confidence</span><span><i className="blue"/>Corrected</span><span><i className="purple"/>Verified</span></div>
      <div className="thumb-row"><button className="thumb active"><div><FileText size={16}/></div><small>{isTabular?'Table view':'Page 1'}</small></button>{record.quality?.page_flags?.map((pg:any)=><span key={pg.page} className="page-flag">Page {pg.page}: {pg.flags?.join(', ')}</span>)}<span className="image-state">{original?'Original':'Enhanced'} image</span></div>
    </div>
    <div className="review-detail"><div className="detail-top"><div className="detail-file"><span className="file-icon pdf"><FileText/></span><div><h2>{job.filename}</h2><small>Document ID <code>{job.id}</code> <button title="Copy document ID" onClick={()=>navigator.clipboard?.writeText(job.id)}><Copy size={12}/></button></small></div></div><Badge tone={record.review?.state==='approved'?'green':record.review?.state==='rejected'?'red':'amber'} icon={record.review?.state==='approved'?BadgeCheck:Clock3}>{record.review?.state==='approved'?'Approved':record.review?.state==='rejected'?'Rejected':'In review'}</Badge></div>
      {job.status==='failed'&&<div className="failed-banner"><AlertCircle size={16}/><div><b>{job.error||'This document could not be processed.'}</b><small>Review the error details and try processing it again.</small></div><button className="button-outline" onClick={()=>retryJob(job.id)}><RefreshCw size={13}/> Retry job</button></div>}
      {ready.vlm==='unavailable'&&!record.quality?.engines?.sample&&<div className="degraded-banner"><Sparkles size={14}/><span>Degraded mode: VLM unavailable</span><small>Rules and OCR are still available for review.</small></div>}
      {missingFields.length>0&&record.review?.state==='pending'&&<div className="review-banner"><AlertCircle size={16}/><div><b>{missingFields.length} fields need your attention</b><small>Start with {label(missingFields[0][0])} and verify the extracted value.</small></div><button onClick={()=>fieldFocus(`invoice.${missingFields[0][0]}`)}>Jump to first <ArrowRight size={14}/></button></div>}
      <div className="record-switch"><span>DOCUMENT</span><select value={selectedDoc} onChange={e=>setSelectedDoc(Number(e.target.value))}>{(mockEnvelope.documents||[record]).map((_:any,i:number)=><option key={i} value={i}>Invoice {String(i+1).padStart(2,'0')} · {record.invoice?.invoice_no?.value||'INV/24/001'}</option>)}</select><span className="record-count">{selectedDoc+1} of {(mockEnvelope.documents||[record]).length}</span></div>
      <div className="detail-tabbar" role="tablist">{tabs.map(t=><button role="tab" aria-selected={tab===t} key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}{t==='Validation'&&record.validation?.checks?.some((c:CheckType)=>!c.passed&&c.severity==='warning')&&<i className="tab-alert"/>}</button>)}</div>
      <div className="tab-content" key={tab}>{tab==='Summary'&&<div className="summary-content">{groups.map(([group,keys]:any)=><div className="field-group" key={group}><div className="field-group-title">{group}<span>{keys.filter((k:string)=>invoice[k]?.value!=null).length} fields</span></div>{keys.filter((k:string)=>invoice[k]).map((key:string)=><FieldRow key={key} path={`invoice.${key}`} field={invoice[key]} unmeasured={!!record.quality?.engines?.sample} selected={selectedField===`invoice.${key}`} onSelect={fieldFocus} onEdit={()=>setEdit({path:`invoice.${key}`,value:String(invoice[key]?.value??'')})}/>)}</div>)}<div className="edit-hint"><Pencil size={13}/> Select the pencil to correct a field. Changes are sent to the validation service.</div></div>}
      {tab==='Line items'&&<LineItems record={record} unmeasured={!!record.quality?.engines?.sample} selectedField={selectedField} onSelect={fieldFocus} onEdit={(path:string,v:string)=>setEdit({path,value:v})}/>}
      {tab==='Validation'&&<Validation checks={record.validation?.checks||[]} onJump={(path:string)=>fieldFocus(path)}/>}
      {tab==='Corrections'&&<Corrections record={record}/>}
      {tab==='Duplicates'&&<Duplicates record={record} jobs={jobs} openJob={openJob}/>}
      {tab==='Table'&&<DataTable record={record} selectedField={selectedField} onSelect={fieldFocus}/>}
      {tab==='Audit'&&<Audit record={record}/>}
      {tab==='JSON'&&<div className="json-view"><div className="json-toolbar"><b><FileJson2 size={15}/> Record JSON</b><button onClick={()=>setExpandedJson(!expandedJson)}>{expandedJson?'Collapse':'Expand'} <ChevronDown size={13}/></button><button onClick={()=>navigator.clipboard?.writeText(JSON.stringify(record,null,2))}><Copy size={13}/> Copy</button></div>{expandedJson&&<pre>{JSON.stringify(record,null,2)}</pre>}</div>}
      {tab==='Pipeline'&&<Pipeline quality={record.quality} status={ready}/>}
      </div>
      <div className="detail-actions"><div className="export-actions"><select value={scope} onChange={e=>setScope(e.target.value)} aria-label="Export scope"><option value="exportable">Exportable only</option><option value="all">All documents</option></select><button className="button-outline" onClick={()=>exportFile('json')}><FileJson2 size={15}/> JSON</button><button className="button-outline" onClick={()=>exportFile('csv')}><FileSpreadsheet size={15}/> CSV</button><button className="button-outline" onClick={()=>exportFile('xlsx')}><ArrowDownToLine size={15}/> XLSX</button></div><div className="review-buttons">{record.review?.state==='approved'?<button className="button-outline" onClick={()=>doReview('reopen')}>Reopen</button>:<><button className="button-outline reject" onClick={()=>doReview('reject')}><XCircle size={15}/> Reject</button><button className="button-primary approve" onClick={()=>doReview('approve')}><CheckCircle2 size={15}/> Approve &amp; export</button></>}</div></div>
    </div></div>
    {edit&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setEdit(null)}><form className="edit-modal" onSubmit={e=>{e.preventDefault();saveEdit()}}><div className="modal-heading"><div><span className="eyebrow">CORRECT EXTRACTED VALUE</span><h2>{label(editKey)}</h2></div><button type="button" className="icon-button" onClick={()=>setEdit(null)}><X size={18}/></button></div><label>Verified value<input autoFocus value={edit.value} onChange={e=>setEditValue(e.target.value)} /></label><p>Saving records a reviewer correction and refreshes validation.</p><div className="modal-actions"><button type="button" className="button-outline" onClick={()=>setEdit(null)}>Cancel</button><button className="button-primary"><Check size={15}/> Save correction</button></div></form></div>}
  </section>}

function FieldRow({path,field,selected,onSelect,onEdit,unmeasured}:any){const key=path.split('.').pop();const tone=unmeasured?'neutral':statusTone(field.status,field.confidence);return <div className={`field-row ${selected?'field-selected':''}`} tabIndex={0} onClick={()=>onSelect(path)} onKeyDown={e=>e.key==='Enter'&&onSelect(path)}><div className="field-main"><span className="field-label">{label(key)}</span><b className={field.value==null?'muted-value':''}>{key?.match(/subtotal|discount|taxable_value|cgst|sgst|igst|cess|total_tax|round_off|total_amount|unit_price|line_total/) ?money(field.value):field.value??'Not found'}</b>{field.note&&<small>{field.note}</small>}</div><div className="field-meta"><span className={`confidence ${tone}`}>{unmeasured?'—':`${Math.round((field.confidence||0)*100)}%`}</span><span className={`field-state ${tone}`}><i/>{unmeasured?'Ground truth':field.status==='human_verified'?'Verified':field.status==='needs_review'?'Review':field.status==='missing'?'Missing':field.status==='corrected'?'Corrected':field.status==='derived'?'Derived':'Accepted'}</span><button className="edit-icon" title={`Edit ${label(key)}`} aria-label={`Edit ${label(key)}`} onClick={e=>{e.stopPropagation();onEdit()}}><Pencil size={14}/></button></div></div>}
function DocumentCanvas({record,filename,selectedField,setSelectedField,zoom,original,fileView}:any){const all=Object.entries(record.invoice||{}).filter(([_,v]:any)=>v?.bbox);const isImage=!!fileView?.type?.startsWith('image/');const imageUrl=useMemo(()=>isImage?URL.createObjectURL(fileView):null,[fileView,isImage]);useEffect(()=>()=>{if(imageUrl)URL.revokeObjectURL(imageUrl)},[imageUrl]);const overlays=all.map(([k,v]:any)=>{const b=v.bbox;return <button key={k} title={`${label(k)} · ${v.value??'Missing'} · ${Math.round((v.confidence||0)*100)}% · ${(v.sources||[]).join(', ')}`} aria-label={`Highlight ${label(k)}`} onClick={()=>setSelectedField(`invoice.${k}`)} className={`bbox ${statusTone(v.status,v.confidence)} ${selectedField===`invoice.${k}`?'highlighted':''}`} style={{left:`${b.x0*100}%`,top:`${b.y0*100}%`,width:`${(b.x1-b.x0)*100}%`,height:`${(b.y1-b.y0)*100}%`}}/>});return <div className={`document-canvas ${filename.includes('photo')||filename.includes('jpg')?'photo-canvas':''}`}>{imageUrl?<div className="uploaded-image"><img src={imageUrl} alt={`Uploaded document ${filename}`} style={{transform:`scale(${zoom/100})`,filter:original?'none':'contrast(1.02) brightness(1.02)'}}/>{overlays}</div>:<div className="paper" style={{transform:`scale(${zoom/100})`}}><div className="paper-brand"><span>V</span><div><b>GLOBAL TECH</b><small>SOLUTIONS</small></div><strong>TAX INVOICE</strong></div><div className="paper-rule"/><div className="paper-top"><div><small>FROM</small><b>Global Tech Solutions</b><span>402, Tech Park, Andheri East</span><span>Mumbai, Maharashtra 400069</span><span>GSTIN: 27AAACG0000Z1Z5</span></div><div><small>INVOICE DETAILS</small><span><b>Invoice no.</b> INV/24/001</span><span><b>Date</b> 12 Jan 2024</span><span><b>Place of supply</b> Maharashtra</span></div></div><div className="paper-billto"><small>BILL TO</small><b>Cloudwise Technologies Pvt. Ltd.</b><span>GSTIN: 27AAPFU0939F1ZV</span></div><table className="paper-items"><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody><tr><td>Cloud Hosting - Enterprise</td><td>1</td><td>145,000</td><td>145,000</td></tr><tr><td>Premium Support 24/7</td><td>1</td><td>36,355</td><td>36,355</td></tr></tbody></table><div className="paper-bottom"><small>Thank you for your business.</small><div><span>Subtotal <b>₹1,81,355.00</b></span><span>CGST <b>₹16,322.00</b></span><span>SGST <b>₹16,323.00</b></span><strong>TOTAL <b>₹2,14,000.00</b></strong></div></div>{overlays}<span className="paper-page">1 / 1</span>{original&&<span className="original-tag">ORIGINAL</span>}</div>}</div>}
function LineItems({record,selectedField,onSelect,onEdit,unmeasured}:any){const lines=(record.line_items||[]).map((l:any,i:number)=>({i,...l})).sort((a:any,b:any)=>Number(a.line_no?.value||0)-Number(b.line_no?.value||0));if(!lines.length)return <EmptyState title="No line items found" text="When line items are extracted, they'll appear here." icon={Table2}/>;const cols=['line_no','description','hsn_sac','quantity','unit_price','tax_rate','taxable_value','line_total'];return <div className="table-wrap"><table className="data-table line-table"><thead><tr>{cols.map(c=><th key={c}>{label(c)}</th>)}</tr></thead><tbody>{lines.map((line:any)=><tr key={line.i}>{cols.map(c=>{const f=line[c]||{};const path=`line_items[${line.i}].${c}`;const need=f.status==='needs_review'||f.status==='missing';return <td key={c} className={`${need?'needs-cell':''} ${selectedField===path?'selected-cell':''}`} onClick={()=>onSelect(path)} title={f.source_ref||f.evidence_text||''}><div><span>{f.value==null?'—':c.match(/unit_price|taxable_value|line_total/)?money(f.value):f.value}</span>{unmeasured?<small className="confidence neutral">ground truth</small>:f.confidence>0&&<small className={`confidence ${statusTone(f.status,f.confidence)}`}>{Math.round(f.confidence*100)}%</small>}{need&&<button aria-label={`Edit ${label(c)}`} onClick={e=>{e.stopPropagation();onEdit(path,String(f.value??''))}}><Pencil size={12}/></button>}</div></td>})}</tr>)}</tbody></table><div className="table-summary">{lines.length} line items <span>Scroll to see all columns <ArrowRight size={12}/></span></div></div>}
function Validation({checks,onJump}:any){if(!checks.length)return <EmptyState title="No validation checks" text="Checks from the validation service will appear here." icon={BadgeCheck}/>;const groups=['error','warning','info'];return <div className="validation-content">{groups.map(sev=>{const list=checks.filter((c:CheckType)=>c.severity===sev);if(!list.length)return null;return <section className="check-group" key={sev}><h3><span className={`severity-icon ${sev}`}>{sev==='error'?<XCircle size={15}/>:sev==='warning'?<AlertCircle size={15}/>:<CheckCircle2 size={15}/>}</span>{label(sev)}s <small>{list.length}</small></h3>{list.map((c:CheckType,i:number)=><article className={`check-card ${!c.passed&&sev!=='info'?'check-fail':''}`} key={`${c.code}-${i}`}><div><b>{c.code.replaceAll('_',' ')}</b><span className={`check-result ${c.passed?'passed':'failed'}`}>{c.passed?'Passed':'Review'}</span></div><p>{c.message}</p>{(c.expected||c.actual||c.difference)&&<div className="check-values">{c.expected&&<span><small>Expected</small><b>{c.expected}</b></span>}{c.actual&&<span><small>Actual</small><b>{c.actual}</b></span>}{c.difference&&<span><small>Difference</small><b>{c.difference}</b></span>}</div>}{c.field_paths?.map((path:string)=><button className="jump-link" key={path} onClick={()=>onJump(path)}>View {path.split('.').pop()?.replaceAll('_',' ')} <ArrowRight size={13}/></button>)}</article>)}</section>})}</div>}
function Corrections({record}:any){const corrections=record.validation?.corrections||[];return corrections.length?<div className="corrections-list">{corrections.map((c:any,i:number)=><article key={i} className="correction-card"><Badge tone="blue">{c.method}</Badge><h3>{label(c.field_path.split('.').pop())}</h3><div className="correction-values"><span>{c.original??'—'}</span><ArrowRight size={15}/><b>{c.corrected??'—'}</b></div><p>{c.reason}</p><small>Confidence {Math.round(c.confidence_before*100)}% → {Math.round(c.confidence_after*100)}%</small></article>)}</div>:<EmptyState title="No corrections yet" text="Automatic repairs and reviewer edits are recorded here." icon={Pencil}/>}
function Duplicates({record,jobs,openJob}:any){const d=record.duplicates||[];return d.length?<div className="duplicate-list">{d.map((x:any,i:number)=><article key={i}><div className="duplicate-icon"><Copy size={17}/></div><div><b>{jobs.find((j:Job)=>j.id===x.other_job_id)?.filename||x.other_job_id}</b><p>{x.kind.replaceAll('_',' ')} match · {Math.round(x.score*100)}% similarity</p><small>{x.reasons.join(' · ')}</small></div><button className="text-link" onClick={()=>{const j=jobs.find((j:Job)=>j.id===x.other_job_id);j&&openJob(j)}}>Open <ArrowRight size={14}/></button></article>)}</div>:<EmptyState title="No duplicates found" text="VYOM+ checks for exact files and matching invoice details." icon={Copy}/>}
function DataTable({record,selectedField,onSelect}:any){const rows=record.line_items||[];return <div className="data-table-content"><div className="mapping-strip"><span><Table2 size={15}/><b>Column mapping</b></span><span>14 fields mapped</span><Badge tone="green">All columns recognized</Badge></div>{rows.length?<LineItems record={record} selectedField={selectedField} onSelect={onSelect} onEdit={()=>{}}/>:<div className="sheet-preview"><table className="data-table"><thead><tr>{['Row','Invoice No.','Date','Supplier','GSTIN','Taxable value','Tax','Total','Source'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{[['12','INV/24/001','12 Jan 2024','Global Tech Solutions','27AAACG0000Z1Z5','₹1,81,355','₹32,645','₹2,14,000','Sheet1!R12'],['13','INV/24/002','15 Jan 2024','Northstar Digital','29ABCDE1234F1ZW','₹84,000','₹15,120','₹99,120','Sheet1!R13'],['14','INV/24/003','17 Jan 2024','Aster Works','07AAACR5055K1Z9','₹32,500','₹5,850','₹38,350','Sheet1!R14']].map(row=><tr key={row[0]}>{row.map((c,i)=><td key={i}>{c}</td>)}</tr>)}</tbody></table><div className="table-summary">3 source rows <span>Hover a row to see source reference</span></div></div>}</div>}
function Audit({record}:any){const history=record.review?.history||[];return history.length?<div className="audit-list">{history.map((event:any,i:number)=><div className="audit-event" key={i}><span className={`audit-symbol ${event.action}`}>{event.action==='approve'?<Check size={14}/>:event.action==='reject'?<X size={14}/>:<Pencil size={13}/>}</span><div><b>{label(event.action)}{event.field_path?` · ${label(event.field_path.split('.').pop())}`:''}</b><small>{event.actor} <i/> {new Date(event.ts).toLocaleString()}</small>{event.old!=null&&<p>{event.old} <ArrowRight size={13}/> {event.new}</p>}</div></div>)}</div>:<EmptyState title="No review activity yet" text="Edits, approvals and rejections will be added to this audit trail." icon={Clock3}/>}
function Pipeline({quality,status}:any){return <div className="pipeline-content"><div className="pipeline-intro"><div className="pipeline-glyph"><Activity size={20}/></div><div><b>{quality?.degraded?'Degraded processing':'Processing complete'}</b><small>{quality?.degraded_reasons?.join(' · ')||'Document processed through the local extraction pipeline.'}</small></div></div><div className="engine-grid">{Object.entries(status||quality?.engines||{}).map(([k,v]:any)=><div key={k}><span className={`engine-indicator ${v==='available'?'up':v==='degraded'?'warn':'down'}`}/><b>{label(k)}</b><small>{String(v)}</small></div>)}</div><h3>Stage timings</h3>{Object.entries(quality?.timings_ms||{}).map(([k,v]:any)=><div className="timing-row" key={k}><span>{label(k)}</span><div><i style={{width:`${Math.min(100,Number(v)/10)}%`}}/></div><b>{v} ms</b></div>)}{quality?.page_flags?.map((p:any)=><p key={p.page}>Page {p.page}: {p.flags.join(', ')}</p>)}</div>}
function EmptyState({title,text,icon:Icon}:any){return <div className="empty-state"><span><Icon size={21}/></span><b>{title}</b><p>{text}</p></div>}

function DashboardPage({jobs,onQueue}:any){const [period,setPeriod]=useState('Jan 1 – Jan 31, 2024');const bars=[42,65,48,74,57,87,62];const total=12482;return <section className="page-content dashboard-page"><div className="page-heading"><div><div className="eyebrow">OVERVIEW <span>·</span> ANALYTICS</div><h1>System Dashboard</h1><p>Monitor document processing and review activity across your workspace.</p></div><button className="button-outline date-select"><Clock3 size={15}/><select value={period} onChange={e=>setPeriod(e.target.value)}><option>Jan 1 – Jan 31, 2024</option><option>Last 7 days</option><option>Last 30 days</option></select><ChevronDown size={14}/></button></div><div className="metric-grid"><Metric title="Invoices processed" value={total.toLocaleString()} change="12%" direction="up" icon={FileText} tone="green"/><Metric title="Accuracy rate" value="98.2%" change="0.4%" direction="up" icon={Gauge} tone="blue"/><Metric title="Pending reviews" value="42" change="5%" direction="down" icon={Clock3} tone="amber"/><Metric title="Avg. processing time" value="1.4s" change="Avg" direction="flat" icon={Activity} tone="violet"/></div><div className="analytics-grid"><div className="analytics-card volume-card"><div className="analytics-heading"><div><h3>Processing volume</h3><small>Documents processed over the last 7 days</small></div><button className="button-outline small">Last 7 days <ChevronDown size={13}/></button></div><div className="chart"><div className="chart-y"><span>800</span><span>600</span><span>400</span><span>200</span><span>0</span></div><div className="chart-plot"><div className="chart-gridlines"><i/><i/><i/><i/><i/></div><svg viewBox="0 0 700 220" preserveAspectRatio="none" aria-label="Invoice processing volume chart"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#249f76" stopOpacity=".18"/><stop offset="1" stopColor="#249f76" stopOpacity="0"/></linearGradient></defs><path d="M0,142 C40,128 50,86 116,99 S190,139 232,78 S307,120 350,64 S420,105 465,56 S530,120 580,51 S650,67 700,25 L700,220 L0,220Z" fill="url(#area)"/><path d="M0,142 C40,128 50,86 116,99 S190,139 232,78 S307,120 350,64 S420,105 465,56 S530,120 580,51 S650,67 700,25" fill="none" stroke="#249f76" strokeWidth="3" vectorEffect="non-scaling-stroke"/></svg><div className="chart-x">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=><span key={x}>{x}</span>)}</div></div></div><div className="chart-legend"><span><i/>Invoices</span><span><i className="legend-gray"/>Receipts</span><span><i className="legend-purple"/>POs</span><span><i className="legend-light"/>Other</span></div></div><div className="analytics-card distribution-card"><div className="analytics-heading"><div><h3>Document distribution</h3><small>By document type</small></div><button className="icon-button"><MoreHorizontal size={18}/></button></div><div className="distribution"><div className="donut"><div><b>12,482</b><small>Total files</small></div></div><div className="dist-legend"><span><i className="dot-invoice"/>Invoices <b>68%</b></span><span><i className="dot-receipt"/>Receipts <b>17%</b></span><span><i className="dot-po"/>Purchase orders <b>9%</b></span><span><i className="dot-other"/>Other <b>6%</b></span></div></div></div></div><div className="activity-card"><div className="analytics-heading"><div><h3>Recent activity</h3><small>Latest documents across your workspace</small></div><button className="text-link" onClick={onQueue}>View history <ArrowRight size={14}/></button></div><div className="activity-table"><div className="activity-head"><span>FILE NAME</span><span>TIME</span><span>CONFIDENCE</span><span>STATUS</span><span/></div>{jobs.slice(0,3).map((j:Job,i:number)=><div className="activity-row" key={j.id}><span><span className={`file-icon ${i===1?'image':'pdf'}`}>{i===1?<FileImage/>:<FileText/>}</span><b>{j.filename}</b></span><span>{i===0?'2 min ago':i===1?'14 min ago':'1 hr ago'}</span><span className={`confidence ${j.confidence>90?'green':'amber'}`}>{j.confidence||'—'}%</span><StatusDot status={j.status}/><button className="row-more" onClick={onQueue}><ArrowRight size={16}/></button></div>)}</div></div></section>}
function Metric({title,value,change,direction,icon:Icon,tone}:any){return <div className="metric-card"><div className={`metric-icon ${tone}`}><Icon size={19}/></div><div className="metric-change">{direction==='up'?<span className="up">↗ +{change}</span>:direction==='down'?<span className="down">↘ -{change}</span>:<span className="neutral-change">{change}</span>}<small>vs last month</small></div><strong>{value}</strong><span>{title}</span></div>}
function SettingsPage({ready,extractor,setExtractor}:any){return <section className="page-content settings-page"><div className="page-heading"><div><div className="eyebrow">WORKSPACE <span>·</span> PREFERENCES</div><h1>Configuration</h1><p>Manage extraction defaults and check local service availability.</p></div></div><div className="settings-card"><div className="settings-card-head"><div className="settings-glyph"><Settings2/></div><div><h2>Extraction preferences</h2><p>These options can be overridden for each upload.</p></div></div><label className="settings-row"><span><b>Default extractor mode</b><small>Choose how VYOM+ should extract information.</small></span><select value={extractor} onChange={e=>setExtractor(e.target.value)}><option value="auto">Automatic</option><option value="rules">Rules only</option><option value="vlm">Vision model</option></select></label><label className="settings-row"><span><b>API endpoint</b><small>The VYOM+ backend used by this frontend.</small></span><code>{API}</code></label></div><div className="settings-card"><div className="settings-card-head"><div className="settings-glyph green"><Activity/></div><div><h2>System readiness</h2><p>Services report their current availability.</p></div></div>{Object.entries(ready).map(([k,v]:any)=><div className="settings-row service-row" key={k}><span><b>{label(k)}</b><small>{k==='vlm'?'Optional vision model':k==='db'?'Job and review storage':'Document processing service'}</small></span><Badge tone={v==='available'?'green':v==='degraded'?'amber':'neutral'}>{v}</Badge></div>)}</div></section>}
